"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[4601],{2891(e){e.exports=JSON.parse('{"title":"\ucd5c\uc2e0 \ud504\ub808\uc784\uc6cc\ud06c\ub294 SPA\ub9cc \uc9c0\uc6d0\ud558\uc9c0 \uc54a\ub294\ub2e4.","date":"2024-11-16","coverUrl":null,"html":"<h2 data-notion-block-id=\\"13fe548d-8a8e-801a-a823-e17b164a841b\\" id=\\"13fe548d-8a8e-801a-a823-e17b164a841b\\">\ucd5c\uc2e0 \ud504\ub808\uc784\uc6cc\ud06c\ub294 SPA\ub9cc \uc9c0\uc6d0\ud558\uc9c0 \uc54a\ub294\ub2e4.</h2><a href=\\"https://jakelazaroff.com/words/whats-a-single-page-app/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://jakelazaroff.com/words/whats-a-single-page-app/</a><p data-notion-block-id=\\"13fe548d-8a8e-80f7-9510-dc916747e890\\"><b>\uc2ec\uc724\uc12d</b>: \uc5ec\ub7ec\uac00\uc9c0 \ud504\ub808\uc784\uc6cc\ud06c\uac00 \ub4f1\uc7a5\ud558\uba74\uc11c \uc608\uc804\uc5d0\ub294 \ud504\ub808\uc784\uc6cc\ud06c\uac00 \ud558\ub098\uc758 \uc544\ud0a4\ud14d\uccd0\uacfc \ud558\ub098\uc758 \ubc29\uc2dd\ub9cc \uc9c0\uc6d0\ud588\uc9c0\ub9cc, SPA\uc758 \ub4f1\uc7a5, \uba54\ud0c0 \ud504\ub808\uc784\uc6cc\ud06c\uc758 \ub4f1\uc7a5, \u2026\uc774 \uc9c4\ud589\ub418\uba74\uc11c \ud55c \ud504\ub808\uc784\uc6cc\ud06c\uac00 \uc5ec\ub7ec\uac00\uc9c0 \uc544\ud0a4\ud14d\uccd0\ub098 \ubc29\uc2dd\uc744 \uc9c0\uc6d0\ud558\uba74\uc11c \uacbd\uacc4\uac00 \uc560\ub9e4\ud574\uc84c\uc2b5\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 SPA/MPA, SSR/CSR\uc758 \ucc28\uc774\ub97c \uc54c\uace0 \uc5b4\ub5a4 \ud504\ub808\uc784\uc6cc\ud06c\uac00 \uc5b4\ub5a4 \ubc29\uc2dd\uc744 \uc9c0\uc6d0\ud558\ub294\uc9c0 \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"13fe548d-8a8e-8060-8889-e87536f16d95\\" id=\\"13fe548d-8a8e-8060-8889-e87536f16d95\\">React 19\uc5d0\uc11c SearchParams \ud578\ub4e4\ub9c1\ud558\uae30</h2><a href=\\"https://aurorascharff.no/posts/managing-advanced-search-param-filtering-next-app-router/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://aurorascharff.no/posts/managing-advanced-search-param-filtering-next-app-router/</a><p data-notion-block-id=\\"13fe548d-8a8e-80e9-b476-e3cc13c63551\\">Next.js App router\uc5d0\uc11c SearchParams\uc640 <code>use</code>\ud6c5\uc744 \ud65c\uc6a9\ud574\uc11c \uac04\ub2e8\ud558\uac8c \ub9cc\ub4e4\uba74 \ub77c\uc6b0\ud305\uc774 \ubc14\ub85c \uc548\ub418\ub294 \ud604\uc0c1\uc744 <code>useTransition</code>, <code>useOptimistic</code> \ud6c5\uc744 \ud65c\uc6a9\ud574\uc11c SearchParams\ub97c \ud65c\uc6a9\ud558\uba74\uc11c \ub85c\ub529 \uc0c1\ud0dc \uad6c\ud604, \ub099\uad00\uc801 \uc5c5\ub370\uc774\ud2b8 \uad6c\ud604\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uac80\uc0c9\uacfc \ud544\ud130\ub9c1\uc744 <a href=\\"https://ones-to-watch.ethansup.net/news/post/117edf84-09ae-4b59-a977-3278116eb17f#287d88a5-2bad-4693-b11b-bda004671758\\"><code>useSearchParams</code></a><a href=\\"https://ones-to-watch.ethansup.net/news/post/117edf84-09ae-4b59-a977-3278116eb17f#287d88a5-2bad-4693-b11b-bda004671758\\">\uc640 \uc11c\ubc84\uc0c1\ud0dc \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \ud1b5\ud574 \uad6c\ud604\ud558\ub294 \uae00</a>\uc740 \uc788\uc5c8\uc9c0\ub9cc, \uc2e0\uc120\ud55c \uc811\uadfc\uc774\ub124\uc694.</p><h2 data-notion-block-id=\\"13fe548d-8a8e-808f-808f-e02fc1f6540e\\" id=\\"13fe548d-8a8e-808f-808f-e02fc1f6540e\\">Barrel File \uc4f0\uc9c0 \ub9c8\uc138\uc694. \uc81c\ubc1c.</h2><a href=\\"https://www.youtube.com/watch?v=YcT2yP0nmm0\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.youtube.com/watch?v=YcT2yP0nmm0</a><p data-notion-block-id=\\"13fe548d-8a8e-80eb-8690-feb18465efb4\\">Webpack to Vite \ub9c8\uc774\uadf8\ub808\uc774\uc158\uc744 \ud1b5\ud574\uc11c \uac1c\ubc1c/\ube4c\ub4dc \uc2dc\uac04\uc744 \ub2e8\ucd95\ud558\ub294 \uac83\uc774 \ud070 \uc8fc\uc81c\uc774\uc9c0\ub9cc, \ub9ce\uc740 \ub0b4\uc6a9\uc774 Barrel File\uc774 \uc65c \uc548 \uc88b\uc740\uc9c0, \uc774\ub97c \uc5b4\ub5bb\uac8c \ud574\uacb0\ud588\ub294\uc9c0\ub97c \ubcf4\uc5ec\uc8fc\ub294 \ubc1c\ud45c\uc785\ub2c8\ub2e4. (\uadf8 \uc678\uc5d0\ub294 loader \ubc29\uc2dd \ucc44\uc6a9\uacfc tree shaking \uad00\ub828). Barrel File\uc744 \uc0ac\uc6a9\ud558\uba74 \uc548\ub418\ub294 \uc774\uc720\ub97c \uc124\uba85\ud55c \uae00 \uc911\uc5d0\uc11c\ub294 <a href=\\"https://ones-to-watch.ethansup.net/news/post/a50a179e-3bb4-4959-83d9-4f5ed59bba5d#66f16eb8-0c22-4281-8d90-a9c2e687f435\\">Tkdodo\uc758 \uae00</a>\ub3c4 \uc88b\uc9c0\ub9cc, \uc138\uc138\ud558\uac8c \ubc88\ub4e4\ub9c1 \uce21\uba74\uc5d0\uc11c \ubcf4\uc5ec\uc918\uc11c \uc88b\uc740 \ubc1c\ud45c\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"13fe548d-8a8e-809b-84f3-f5c5d880472f\\" id=\\"13fe548d-8a8e-809b-84f3-f5c5d880472f\\">\ub370\uc774\ud130 \ub3d9\uae30\ud654 \uc9c0\ud45c</h2><a href=\\"https://stack.convex.dev/a-map-of-sync\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://stack.convex.dev/a-map-of-sync</a><p data-notion-block-id=\\"13fe548d-8a8e-801e-aa91-ebdd0120fa29\\">\uac8c\uc784\ubd80\ud130 \ubb38\uc11c \uc791\uc5c5, \ub2e8\uc21c \ub370\uc774\ud130 \ud504\ub808\uc784\uc6cc\ud06c\uae4c\uc9c0 \ub3d9\uae30\ud654\uc5d0 \uad00\ub828\ub41c \ud50c\ub7ab\ud3fc/\ud504\ub808\uc784\uc6cc\ud06c\uc5d0 \ub300\ud55c \uc9c0\ud45c\ub97c \uc18c\uac1c\ud569\ub2c8\ub2e4. \ub370\uc774\ud130 \ub3d9\uae30\ud654\ub294 \ud611\uc5c5 \uae30\ub2a5 \uad6c\ud604\uacfc \uad00\ub828\uc788\uae30 \ub54c\ubb38\uc5d0, <a href=\\"https://ones-to-watch.ethansup.net/news/post/0269c0cd-b5f8-4f29-8457-f7976befb282#011c26fc-e180-4b41-b912-007040d7fa76\\">\ud611\uc5c5 \uae30\ub2a5 \uad6c\ud604\uc744 \uc704\ud55c \uc544\ud0a4\ud14d\uccd0</a> \uae00\ub3c4 \ubcf4\uc2dc\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"13fe548d-8a8e-80d0-93e3-ea510505e1b1\\" id=\\"13fe548d-8a8e-80d0-93e3-ea510505e1b1\\">CSS reset\uc744 layer\ub85c \uac10\uc2f8\uc57c \ud558\ub294 \uc774\uc720</h2><a href=\\"https://mayank.co/blog/css-reset-layer/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://mayank.co/blog/css-reset-layer/</a><p data-notion-block-id=\\"13fe548d-8a8e-80a7-9782-c31904910948\\"><a href=\\"https://caniuse.com/css-cascade-layers\\">\ucd5c\uadfc CSS \ud45c\uc900</a>\uc73c\ub85c \ub4e4\uc5b4\uc628 <code>@layer</code>(Cascade Layers)\ub97c CSS reset\uc744 \uc0ac\uc6a9\ud560 \ub54c \ud65c\uc6a9\ud574\uc57c \ud55c\ub2e4\uace0 \uc8fc\uc7a5\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uacbd\uc6b0\uc5d0 \ub530\ub77c\uc11c <a href=\\"https://ones-to-watch.ethansup.net/news/post/427a9c3c-eab8-4c52-b1c8-9036c2552ded#b299cd18-fe96-4085-9cfa-392264c86c3d\\">\uba85\uc2dc\ub3c4 \uc18d\uc784\uc218</a>\ub97c \ud1b5\ud574\uc11c \uc2a4\ud0c0\uc77c\uc744 \ubcc0\uacbd\ud574\uc57c \ud558\ub294 \uacbd\uc6b0\ub3c4 \uc0dd\uae38 \uc218 \uc788\uc73c\ub2c8, \ubaa8\ub358 \ube0c\ub77c\uc6b0\uc800\ub97c \uc9c0\uc6d0\ud55c\ub2e4\uba74 \uace0\ub824\ud574\ubcfc\ub9cc\ud558\ub124\uc694. \uc774\uc678\uc5d0\ub3c4 Cascade Layer\uc5d0 \ub300\ud55c \uc124\uba85\uc774\ub098 \uc2a4\ud0c0\uc77c \uacc4\uc0b0 \ubc29\uc2dd\uc744 \uc54c\uace0\uc2f6\ub2e4\uba74 <a href=\\"https://css-tricks.com/css-cascade-layers/\\">CSS-Trick\uc5d0\uc11c\uc758 \uc18c\uac1c \uae00</a>\uc744 \ubcf4\ub294 \uac83\ub3c4 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"13fe548d-8a8e-808f-bd53-eb66218fd93b\\" id=\\"13fe548d-8a8e-808f-bd53-eb66218fd93b\\">JS generator \uc18c\uac1c\ud558\uae30</h2><a href=\\"https://jrsinclair.com/articles/2022/why-would-anyone-need-javascript-generator-functions/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://jrsinclair.com/articles/2022/why-would-anyone-need-javascript-generator-functions/</a><p data-notion-block-id=\\"13fe548d-8a8e-8077-9464-ddb8a35dd3f1\\">JS generator\ub97c \uc18c\uac1c\ud558\uace0, \ud568\uc218\ud615 \ud504\ub85c\uadf8\ub798\ubc0d\uc5d0 \uc5b4\ub5bb\uac8c \uc870\ud569\ub418\ub294\uc9c0\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ub9ce\uc774 \uc0ac\uc6a9\ub418\ub294 \ud328\ud134\uc740 \uc544\ub2c8\uc9c0\ub9cc, React\uc5d0\uc11c \uc0c1\ud0dc \uad00\ub9ac\ub97c \uc704\ud574 \uac00\ub054\uc529 \ubcf4\uc774\ub294 \ud328\ud134\uc774\ubbc0\ub85c(<a href=\\"https://github.com/adobe/react-spectrum/blob/3f44370de69e48ee56cbf2bbd8664cee8294e9fe/packages/%40react-stately/collections/src/CollectionBuilder.ts#L97-L233\\">react-stately</a>, <a href=\\"https://github.com/redux-saga/redux-saga\\">redux-saga</a>) \uc219\uc9c0\ud574\ub458 \ud544\uc694\ub294 \uc788\uc5b4\ubcf4\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"13fe548d-8a8e-8045-9211-f973a93e8aff\\" id=\\"13fe548d-8a8e-8045-9211-f973a93e8aff\\">HTTP/3 \uc368\ubcf4\uc2e4\ub798\uc694?</h2><p data-notion-block-id=\\"143e548d-8a8e-8078-a0ca-e37af68e5495\\"><a href=\\"https://www.cloudflare.com/ko-kr/learning/performance/what-is-http3/\\">https://www.cloudflare.com/ko-kr/learning/performance/what-is-http3/</a></p><p data-notion-block-id=\\"13fe548d-8a8e-8069-87e7-c4c08c5adf69\\">Cloudflare\uc758 HTTP/3\uc758 \ub4f1\uc7a5\ud55c \uc774\uc720, \uc368\uc57c \ud558\ub294 \uc774\uc720\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p>"}')}}]);